-- WowVision_Surroundings: data only. Zone files (generated by wv-surroundings tools/export.py)
-- register themselves here; WowVision's surroundings module reads the list when it enables and
-- unpacks a zone only while the player is in it.
local _, addon = ...

WowVisionSurroundingsData = WowVisionSurroundingsData or { zones = {} }
WowVisionSurroundingsData.places = WowVisionSurroundingsData.places or {}

function addon.addZone(zone)
    table.insert(WowVisionSurroundingsData.zones, zone)
end

-- the places list (WowVision's Alt-F10): per zone file its subzones and the things in them, with
-- where each leads (generated by wv-surroundings tools/destinations.py); small, read at once
function addon.addPlaces(places)
    table.insert(WowVisionSurroundingsData.places, places)
end

